# Demo pair 2 shows 7s creating a rectangular structure with 3s
# Let me analyze the exact positions

demo2_input = [
[7, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 7, 7, 9, 9, 9, 9, 9],
[9, 9, 9, 9, 7, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
[9, 9, 9, 9, 7, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
[9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 7],
[9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
]

demo2_output = [
[7, 9, 9, 3, 3, 3, 9, 9, 9, 9, 9, 3, 7, 7, 3, 9, 9, 9, 9],
[9, 9, 9, 3, 7, 3, 9, 9, 9, 9, 9, 3, 3, 3, 3, 9, 9, 9, 9],
[9, 9, 9, 3, 7, 3, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
[9, 9, 9, 3, 3, 3, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 7],
[9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
]

def find_pattern_positions(grid, pattern_val):
    positions = []
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == pattern_val:
                positions.append((i, j))
    return positions

print("Input 7s positions:")
input_pos = find_pattern_positions(demo2_input, 7)
for p in input_pos:
    print(p)

print("\nOutput non-9 positions:")
output_pos = []
for i, row in enumerate(demo2_output):
    for j, val in enumerate(row):
        if val != 9:
            output_pos.append((i, j, val))
            print(f"({i},{j}) = {val}")

# The 7s stay at original positions
print(f"\n7s at same positions: 7s position in input: {input_pos}")
print(f"7s in output: ", end="")
for p, v in output_pos:
    if v == 7:
        print(f"{p} ", end="")
print()

# Where are the 3s?
print("\n3s positions:")
for p, v in output_pos:
    if v == 3:
        print(f"{p}")

print("7s in output:", end="")
for i, row in enumerate(demo2_output):
    for j, val in enumerate(row):
        if val == 7:
            print(f"({i},{j}) ", end="")
print()

# Let me think about this differently
# Look at the structure: 7s seem to form a set of connected components
# Within each component, the 3s fill the "interior" rectangle edges

# Actually, let me check if 3s appear at ALL cells between any two 7s 
# that share either same row or same column

def should_have_3(s, t, input_grid):
    """Check if cells between positions s (row1, col1) and t (row2, col2) 
       should have 3s based on input 7 positions"""
    r1, c1 = s
    r2, c2 = t

    # Find input 7 positions
    input_7s = [(i,j) for i in range(len(input_grid)) for j in range(len(input_grid[0])) 
               if input_grid[i][j] == 7]

    # Rule: if two 7s share a row (same r) or share a column (same c),
    # draw horizontal or vertical edges between them with 3s
    # Also, if a "bend" can be made (one horizontal then one vertical),
    # the corner cells also get 3s

    # For simplicity, let's just draw:
    # Horizontal: row r1 from min(c1,c2) to max-1 
    # Vertical: col c1 from min(r1,r2) to max-1

    three_cells = set()

    # Check horizontal connections
    if r1 == r2:
        for c in range(min(c1, c2) + 1, max(c1, c2)):
            if (r1, c) in input_7s:
                continue
            three_cells.add((r1, c))

    # Check vertical connections  
    if c1 == c2:
        for r in range(min(r1, r2) + 1, max(r1, r2)):
            if (r, c1) in input_7s:
                continue
            three_cells.add((r, c1))

    return three_cells

input_7s = [(0, 0), (0, 12), (0, 13), (1, 4), (2, 4), (3, 18)]
all_threes = set()

for i in range(5):
    for j in range(19):
        if demo2_output[i][j] == 7:
            for r in range(5):
                for c in range(19):
                    if (r,c) in input_7s:
                        all_threes.update(should_have_3((i,j), (r,c), [None]*5))
            for c in range(19):
                for r in range(5):
                    if (r,c) in input_7s:
                        all_threes.update(should_have_3((i,j), (r,c), [None]*5))

print("Generated 3s:", all_threes)
print("Actual 3s:  ", [(i,j) for i in range(5) for j in range(19) if demo2_output[i][j] == 3])
print("Match:", all_threes == set([(i,j) for i in range(5) for j in range(19) if demo2_output[i][j] == 3]))

# Simpler approach - analyze the pattern directly
# The rule appears to be: if 7s form a right angle, fill the edges with 3s

# Key observation: 3s appear between 7s that are connected via a right angle
# e.g., (0,0) and (1,4) connect via corner (0,4) - but (0,4) gets 3, not 7
# Wait, (0,4) in output is 3, not 7. So the path is (0,0)->...->(0,4)->(1,4)

# Let me check horizontal then vertical connections
input_7s = {(0, 0), (0, 12), (0, 13), (1, 4), (2, 4), (3, 18)}
actual_3s = {(0,3),(0,4),(0,5),(0,11),(0,14),(1,3),(1,5),(1,11),(1,12),(1,13),(1,14),(2,3),(2,5),(3,3),(3,4),(3,5)}

# Find 7s that share a row
row_7s = {}
for r in range(5):
    cols = [c for c in range(19) if (r,c) in input_7s]
    if cols:
        row_7s[r] = cols

print("7s by row:", row_7s)

# Find 7s that share a column
col_7s = {}
for c in range(19):
    rows = [r for r in range(5) if (r,c) in input_7s]
    if rows:
        col_7s[c] = rows

print("7s by col:", col_7s)

# Generate horizontal edges
generated = set()
for r, cols in row_7s.items():
    if len(cols) >= 2:
        sorted_cols = sorted(cols)
        for i in range(len(sorted_cols) - 1):
            for c in range(sorted_cols[i] + 1, sorted_cols[i+1]):
                generated.add((r, c))

print("\nHorizontal edges:", generated)

# Generate vertical edges
for c, rows in col_7s.items():
    if len(rows) >= 2:
        sorted_rows = sorted(rows)
        for i in range(len(sorted_rows) - 1):
            for r in range(sorted_rows[i] + 1, sorted_rows[i+1]):
                generated.add((r, c))

print("Vertical edges:", generated)

# Test the "extend lines in cardinal directions" theory

# For each 7, project lines up/down/left/right until hitting edge or another 7
# Fill those projected cells with 3s

input_7s = set([(0, 0), (0, 12), (0, 13), (1, 4), (2, 4), (3, 18)])
generated_3s = set()

for (ri, ci) in input_7s:
    # Project up
    for r in range(ri - 1, -1, -1):
        generated_3s.add((r, ci))
        if (r, ci) in input_7s:
            break

    # Project down
    for r in range(ri + 1, 5):
        generated_3s.add((r, ci))
        if (r, ci) in input_7s:
            break

    # Project left
    for c in range(ci - 1, -1, -1):
        generated_3s.add((ri, c))
        if (ri, c) in input_7s:
            break

    # Project right
    for c in range(ci + 1, 19):
        generated_3s.add((ri, c))
        if (ri, c) in input_7s:
            break

print("Generated 3s:", generated_3s)
print("Actual 3s:  ", {(i,j) for i in range(5) for j in range(19) if demo2_output[i][j] == 3})
print("Match:", generated_3s == {(i,j) for i in range(5) for j in range(19) if demo2_output[i][j] == 3})
